frappe.listview_settings['Event'] = {
    onload: function(listview) {
        // Switch to calendar on initial load
        if (!listview._switched_to_calendar) {
            listview._switched_to_calendar = true;
            setTimeout(() => {
                if (frappe.get_route()[2] !== 'Calendar') {
                    frappe.set_route('List', 'Event', 'Calendar');
                }
            }, 150);
        }
    }
};

// Hook into route changes to catch all navigation scenarios
$(document).on('app_ready', function() {
    frappe.router.on('change', function() {
        let route = frappe.get_route();

        // Check if navigating to Event List view
        if (route[0] === 'List' && route[1] === 'Event' && route[2] !== 'Calendar') {
            // Small delay to let the page load
            setTimeout(() => {
                frappe.set_route('List', 'Event', 'Calendar');
            }, 100);
        }
    });
});

// Client Script for Sales Order - Set Calendar View as Default
// Handles all navigation scenarios including search and breadcrumb clicks

frappe.listview_settings['Sales Order'] = {
    onload: function(listview) {
        // Switch to calendar on initial load
        if (!listview._switched_to_calendar) {
            listview._switched_to_calendar = true;
            setTimeout(() => {
                if (frappe.get_route()[2] !== 'Calendar') {
                    frappe.set_route('List', 'Sales Order', 'Calendar');
                }
            }, 150);
        }
    }
};

// Hook into route changes to catch all navigation scenarios
$(document).on('app_ready', function() {
    frappe.router.on('change', function() {
        let route = frappe.get_route();

        // Check if navigating to Sales Order List view
        if (route[0] === 'List' && route[1] === 'Sales Order' && route[2] !== 'Calendar') {
            // Small delay to let the page load
            setTimeout(() => {
                frappe.set_route('List', 'Sales Order', 'Calendar');
            }, 100);
        }
    });
});

// Handle search results - when user searches "sales order" from awesomebar
$(document).on('click', '[data-route^="List/Sales Order"]', function(e) {
    e.preventDefault();
    frappe.set_route('List', 'Sales Order', 'Calendar');
});

// Handle breadcrumb clicks - when clicking "Sales Order" from inside a record
$(document).on('click', '.breadcrumb-item a[href*="Sales Order"]', function(e) {
    let href = $(this).attr('href');

    // Check if it's a link to the list view
    if (href && (href.includes('/app/sales-order') || href.includes('List/Sales Order'))) {
        e.preventDefault();
        frappe.set_route('List', 'Sales Order', 'Calendar');
    }
});

// Additional handler for awesomebar navigation
frappe.ui.toolbar.Awesomebar && $(document).on('awesomebar:navigate', function(e, data) {
    if (data && data.route && data.route.includes('Sales Order') && data.type === 'List') {
        setTimeout(() => {
            frappe.set_route('List', 'Sales Order', 'Calendar');
        }, 100);
    }
});

frappe.ui.form.on('POS Invoice', {
    customer(frm) {

        $(document).on('shown.bs.modal', '.modal', function() {
            let modal = $(this);

            // Hide specific fields and sections
            modal.find('.frappe-control[data-fieldname="customer_group"]').hide();
            modal.find('.frappe-control[data-fieldname="territory"]').hide();
            modal.find('.modal-footer .custom-actions button:contains("Edit Full Form")').remove();

            // Copy customer name to mobile number
            let nameField = modal.find('.frappe-control[data-fieldname="customer_name"] input');
            let mobileField = modal.find('.frappe-control[data-fieldname="mobile_number"] input');

            // Copy only if the input is number
            if (!isNaN(nameField.val())) {
                mobileField.val(nameField.val());
                nameField.val('');
            }

            // Slide down modal body after hiding fields
            modal.find('.modal-body, .ui-front').slideDown();

            // Set focus to specific fields
            modal.find('input[data-fieldname="customer_name"]').focus();
            modal.find('input[data-fieldname="comment"]').focus();

            // Listen for click on the save button
            modal.find('.modal-footer .standard-actions .btn-modal-primary').click(function(e) {
                if (isNaN(nameField.val() === '')) {
                    nameField.val(mobileField.val());
                }
            });
        });
    }
});

